import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    exams = []

    for i in range(n):
        a_i = int(data[2 * i + 1])
        b_i = int(data[2 * i + 2])
        exams.append((a_i, b_i))

    exams.sort()

    current_day = 0

    for a_i, b_i in exams:
        if b_i > current_day:
            current_day = b_i
        else:
            current_day = a_i

    print(current_day)

